INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a06','O rio que reaparece depois da chuva','rio-reaparece-depois-da-chuva','Em alguns bairros, a água revela o percurso de cursos d’água escondidos sob ruas e construções.','["Depois de uma chuva forte, a água procura o caminho mais antigo. Ela atravessa terrenos baixos, encontra uma passagem entre muros e pode reaparecer onde a cidade imaginava ter encerrado seu curso.","Entender esse percurso exige combinar memória dos moradores, mapas e observação do terreno. Cada uma dessas fontes revela uma parte diferente da relação entre drenagem, ocupação urbana e ambiente.","Reconhecer a água como parte do território ajuda a pensar soluções que não dependam apenas de afastá-la depressa. Também abre espaço para recuperar áreas de infiltração e reduzir riscos para quem vive perto."]','natureza','davi-moraes','','Pequeno curso d’água atravessando uma paisagem verde','published',0,1,'2026-11-19T12:00:00.000Z','2026-11-19T12:00:00.000Z','O rio que reaparece depois da chuva | Pé de Prosa','Em alguns bairros, a água revela o percurso de cursos d’água escondidos sob ruas e construções.');
