INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a10','A oficina comunitária que conserta mais do que objetos','oficina-comunitaria-conserta-mais','Compartilhar ferramentas e conhecimentos reduz o descarte e aproxima pessoas que talvez nunca se encontrassem.','["Uma cadeira bamba chega à oficina numa manhã de sábado. Enquanto alguém procura a chave certa, outra pessoa conta que guardou aquele móvel por causa de uma lembrança.","O reparo compartilhado combina prática e conversa. Quem sabe consertar aprende a explicar; quem chega com uma dúvida descobre que algumas soluções dependem mais de paciência do que de equipamento caro.","Consertar em conjunto também altera a relação com o descarte. O objeto continua em uso, e o conhecimento que permitiu recuperá-lo circula para outras casas."]','ideias','bia-sampaio','','Ferramentas organizadas sobre uma bancada de madeira','published',0,1,'2026-11-15T12:00:00.000Z','2026-11-15T12:00:00.000Z','A oficina comunitária que conserta mais do que objetos | Pé de Prosa','Compartilhar ferramentas e conhecimentos reduz o descarte e aproxima pessoas que talvez nunca se encontrassem.');
