INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a12','O tempo de aprender uma ferramenta nova','tempo-aprender-ferramenta-nova','A adoção de uma tecnologia depende menos do entusiasmo inicial do que do tempo reservado para experimentar e ajustar.','["Uma ferramenta nova costuma chegar acompanhada de uma promessa de agilidade. No cotidiano, porém, alguém precisa aprender onde ficam as funções, adaptar uma tarefa e descobrir como pedir ajuda.","O tempo de aprendizagem raramente aparece no planejamento. Quando a mudança é tratada como simples troca de botão, os obstáculos recaem sobre quem precisa seguir trabalhando enquanto aprende.","Reservar espaço para testar, registrar dúvidas e rever processos torna a adoção mais realista. A tecnologia começa a ajudar quando se encaixa no trabalho que as pessoas de fato fazem."]','trabalho','lucas-reis','','Caderno de anotações ao lado de um teclado e ferramentas de trabalho','published',0,1,'2026-11-13T12:00:00.000Z','2026-11-13T12:00:00.000Z','O tempo de aprender uma ferramenta nova | Pé de Prosa','A adoção de uma tecnologia depende menos do entusiasmo inicial do que do tempo reservado para experimentar e ajustar.');
