INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a13','O desenho de uma cozinha conta como a casa funciona','desenho-cozinha-conta-casa','O lugar dos utensílios, a circulação e a mesa revelam rotinas que uma planta baixa nem sempre consegue explicar.','["Uma cozinha é desenhada por hábitos. A panela mais usada fica perto do fogão; a mesa pode servir para a refeição, a tarefa da escola ou uma conversa que se estende.","Essas escolhas dependem de espaço, orçamento e de quem participa das tarefas. Uma cozinha funcional não é apenas bonita: ela permite que as pessoas circulem e encontrem o que precisam.","Observar a rotina antes de mudar o ambiente ajuda a evitar soluções que fotografam bem, mas dificultam o trabalho de todo dia."]','cotidiano','joana-melo','','Utensílios de cozinha, panela e ervas frescas sobre uma bancada','published',0,1,'2026-11-12T12:00:00.000Z','2026-11-12T12:00:00.000Z','O desenho de uma cozinha conta como a casa funciona | Pé de Prosa','O lugar dos utensílios, a circulação e a mesa revelam rotinas que uma planta baixa nem sempre consegue explicar.');
