INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a15','O clube de leitura que cabe numa hora de almoço','clube-leitura-hora-almoco','Encontros curtos podem sustentar uma comunidade de leitura quando a escolha do livro e o horário respeitam a rotina.','["O grupo escolheu um conto curto e combinou de se encontrar na mesma mesa toda quinta-feira. Ninguém precisava terminar um livro inteiro para participar.","O formato diminuto reduziu a barreira de entrada. Cada pessoa chegava com uma leitura diferente, e a conversa encontrava pontos em comum sem exigir que todos tivessem a mesma interpretação.","Um clube de leitura pode crescer sem transformar o encontro em obrigação. Às vezes, uma hora recorrente é o suficiente para que a leitura encontre lugar na semana."]','cultura','ana-luz','','Livro aberto sobre uma mesa com xícara e marca-página','returned',0,1,NULL,'2026-11-10T12:00:00.000Z','O clube de leitura que cabe numa hora de almoço | Pé de Prosa','Encontros curtos podem sustentar uma comunidade de leitura quando a escolha do livro e o horário respeitam a rotina.');
