INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a17','O que muda quando a escola abre a biblioteca à comunidade','escola-abre-biblioteca-comunidade','Compartilhar um acervo exige combinar acesso, cuidado e horários com as pessoas que vivem ao redor da escola.','["A biblioteca escolar já tem uma função importante para estudantes. Quando abre as portas a outras pessoas do bairro, o espaço ganha novas rotinas e novas perguntas.","É preciso combinar horários, empréstimos e responsabilidades. Uma regra simples, construída com quem vai usar o acervo, pode proteger os livros sem transformar o acesso em um percurso difícil.","A abertura aproxima escola e comunidade por meio de algo concreto: um lugar para ler, pesquisar e encontrar outras pessoas em torno do conhecimento."]','ideias','bia-sampaio','','Estantes de livros e uma porta aberta para uma pequena área verde','draft',0,1,NULL,'2026-11-08T12:00:00.000Z','O que muda quando a escola abre a biblioteca à comunidade | Pé de Prosa','Compartilhar um acervo exige combinar acesso, cuidado e horários com as pessoas que vivem ao redor da escola.');
