INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a18','O que as embalagens dizem sobre o nosso lixo','embalagens-dizem-sobre-nosso-lixo','Seguir a embalagem depois da compra ajuda a entender por que reciclar depende de desenho, coleta e infraestrutura.','["Uma embalagem começa a chamar atenção quando precisa ser descartada. O material, o tamanho e a combinação de camadas determinam o que pode acontecer depois do uso.","A reciclagem depende de escolhas feitas antes da lixeira: como o produto foi pensado, se existe coleta adequada e se o material encontra uma cadeia de reaproveitamento.","Reduzir o problema exige olhar para o sistema inteiro. A responsabilidade não cabe apenas a quem separa o lixo em casa; também envolve quem fabrica, vende e organiza a coleta."]','ideias','maira-costa','','Potes reutilizáveis, papel e recipientes organizados para separar materiais','archived',0,1,NULL,'2026-11-07T12:00:00.000Z','O que as embalagens dizem sobre o nosso lixo | Pé de Prosa','Seguir a embalagem depois da compra ajuda a entender por que reciclar depende de desenho, coleta e infraestrutura.');
