INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a19','A rua que acorda antes do comércio','rua-acorda-antes-comercio','Antes das portas abertas, a cidade já está em movimento: limpeza, entrega, café passado e conversa na calçada.','["Às cinco e pouco, a rua ainda parece vazia para quem olha de uma janela. No nível do chão, porém, uma sequência de tarefas já começou: alguém varre a frente da loja, uma van descarrega caixas e o primeiro café do dia encontra quem está indo trabalhar.","Esses movimentos raramente entram nos retratos mais conhecidos da cidade. Eles não têm a pressa do horário de pico nem a pausa do fim da tarde, mas preparam os lugares para que o restante do dia aconteça. A abertura de uma porta depende de gente que chegou antes.","Observar a manhã cedo ajuda a perceber que uma rua não tem um único horário. Cada pessoa encontra nela um ritmo diferente, e o comércio de bairro se constrói nessa sobreposição de rotinas."]','cidade','caio-nunes','','Fotografia editorial relacionada à matéria: A rua que acorda antes do comércio','published',0,1,'2026-11-25T12:00:00.000Z','2026-11-25T12:00:00.000Z','A rua que acorda antes do comércio | Pé de Prosa','Antes das portas abertas, a cidade já está em movimento: limpeza, entrega, café passado e conversa na calçada.');
