INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a20','O mapa afetivo feito de pontos de referência','mapa-afetivo-pontos-referencia','Para encontrar um endereço, muita gente ainda prefere a padaria, a mangueira ou a esquina conhecida ao nome da rua.','["Um endereço pode ser explicado por números e placas, mas a conversa costuma escolher outras referências: vire depois da padaria, atravesse onde fica a árvore grande, procure a casa de muro azul. O caminho ganha uma linguagem própria.","Esses marcos condensam lembranças e acordos cotidianos. Quem mora perto sabe quando a loja mudou de dono ou quando a árvore perdeu um galho; quem chega pela primeira vez recebe um roteiro que combina orientação com acolhimento.","Mapas digitais ajudam a encontrar coordenadas, mas não substituem esse conhecimento vivido. Perguntar como as pessoas descrevem seus trajetos revela o que faz um lugar ser reconhecido por quem o usa."]','cidade','pedro-alves','','Fotografia editorial relacionada à matéria: O mapa afetivo feito de pontos de referência','published',0,1,'2026-11-24T12:00:00.000Z','2026-11-24T12:00:00.000Z','O mapa afetivo feito de pontos de referência | Pé de Prosa','Para encontrar um endereço, muita gente ainda prefere a padaria, a mangueira ou a esquina conhecida ao nome da rua.');
