INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a23','O som da vizinhança também é um arquivo','som-vizinhanca-arquivo','O barulho da feira, do sino e das brincadeiras registra mudanças que a paisagem visual nem sempre mostra.','["Uma cidade pode ser lembrada pelo som antes de ser lembrada pela imagem. O pregão de um vendedor, a conversa que se estende na porta e o ruído de uma oficina ajudam a reconhecer um bairro sem consultar qualquer placa.","Esses sons mudam com o tempo. Uma atividade fecha, outra ocupa o mesmo ponto, e as regras de convivência precisam ser negociadas de novo entre moradores, trabalhadores e visitantes.","Escutar o entorno é uma forma de perceber a vida pública. O arquivo sonoro de um lugar não é composto apenas por ruídos; ele também guarda horários, ofícios e relações que a pressa costuma deixar passar."]','cultura','maira-costa','','Fotografia editorial relacionada à matéria: O som da vizinhança também é um arquivo','published',0,1,'2026-11-21T12:00:00.000Z','2026-11-21T12:00:00.000Z','O som da vizinhança também é um arquivo | Pé de Prosa','O barulho da feira, do sino e das brincadeiras registra mudanças que a paisagem visual nem sempre mostra.');
