INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a24','Quando a feira termina, começa outro trabalho','quando-feira-termina-outro-trabalho','Desmontar bancas, separar caixas e limpar o espaço faz parte da rotina que mantém a feira viva para o dia seguinte.','["O movimento diminui, as lonas começam a ser dobradas e as caixas vazias se acumulam junto às bancas. Para quem comprou, a feira terminou; para quem trabalhou nela, ainda há uma série de tarefas antes de voltar para casa.","A desmontagem exige separar o que pode ser aproveitado, guardar equipamentos e deixar o espaço em condições de uso. É um trabalho coletivo, embora cada pessoa tenha seu próprio ritmo e seus próprios limites.","Olhar para o fim do expediente completa a imagem da feira. O encontro de algumas horas depende de preparação, manutenção e cuidado que acontecem antes e depois do momento em que as barracas estão abertas."]','cotidiano','joana-melo','','Fotografia editorial relacionada à matéria: Quando a feira termina, começa outro trabalho','published',0,1,'2026-11-20T12:00:00.000Z','2026-11-20T12:00:00.000Z','Quando a feira termina, começa outro trabalho | Pé de Prosa','Desmontar bancas, separar caixas e limpar o espaço faz parte da rotina que mantém a feira viva para o dia seguinte.');
