INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a25','A mesa posta para quem chega sem avisar','mesa-posta-quem-chega-sem-avisar','A hospitalidade aparece em gestos simples, mas também depende do espaço, do tempo e da divisão das tarefas da casa.','["Uma visita inesperada muda a ordem da tarde. A mesa recebe mais um prato, alguém busca copos no armário e a conversa decide se o café será acompanhado por algo que já estava pronto.","A imagem de uma recepção espontânea costuma esconder o trabalho de quem cozinha, organiza e serve. Quando essas tarefas são compartilhadas, a hospitalidade deixa de depender de uma única pessoa e se torna uma prática de grupo.","Receber bem não exige uma produção perfeita. Às vezes, a mesa possível e a atenção ao outro comunicam mais do que um cardápio planejado com antecedência."]','cotidiano','joana-melo','','Fotografia editorial relacionada à matéria: A mesa posta para quem chega sem avisar','published',0,1,'2026-11-19T12:00:00.000Z','2026-11-19T12:00:00.000Z','A mesa posta para quem chega sem avisar | Pé de Prosa','A hospitalidade aparece em gestos simples, mas também depende do espaço, do tempo e da divisão das tarefas da casa.');
