INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a26','O almoço de domingo que mudou de horário','almoco-domingo-mudou-horario','Horários de refeição acompanham mudanças no trabalho, nos deslocamentos e na composição das famílias.','["Durante muito tempo, o almoço de domingo começou quando uma pessoa terminava de cozinhar. Depois, o turno de trabalho mudou, a distância entre as casas aumentou e a refeição passou a esperar por quem chegava mais tarde.","O horário de uma mesa revela a negociação entre rotinas. Algumas famílias mantêm o encontro em outro dia; outras preservam o prato, mas abrem mão de reunir todos ao mesmo tempo.","A tradição não precisa ficar imóvel para continuar sendo reconhecida. Ela pode mudar de hora, de endereço e de formato sem perder a intenção de reservar um espaço para estar junto."]','cotidiano','joana-melo','','Fotografia editorial relacionada à matéria: O almoço de domingo que mudou de horário','published',0,1,'2026-11-18T12:00:00.000Z','2026-11-18T12:00:00.000Z','O almoço de domingo que mudou de horário | Pé de Prosa','Horários de refeição acompanham mudanças no trabalho, nos deslocamentos e na composição das famílias.');
