INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a29','O cartaz que anuncia uma festa antes da música','cartaz-anuncia-festa-antes-musica','Paredes, postes e murais antecipam celebrações e mostram como uma comunidade escolhe convidar seus vizinhos.','["Antes de a primeira nota tocar, a festa já circula em cartazes. A cor, a tipografia e a lista de atrações ocupam os muros e mudam por algumas semanas a paisagem de quem passa pelo mesmo caminho todos os dias.","O anúncio é também uma forma de organização. Ele informa horário, local e quem está envolvido, mas pode carregar marcas de um trabalho feito por artistas, produtores, comerciantes e pessoas que emprestaram um espaço para a divulgação.","Quando o evento termina, alguns cartazes permanecem por mais tempo. Eles registram que a rua recebeu um convite e que, por um período, a expectativa também fez parte da celebração."]','cultura','maira-costa','','Fotografia editorial relacionada à matéria: O cartaz que anuncia uma festa antes da música','published',0,1,'2026-11-15T12:00:00.000Z','2026-11-15T12:00:00.000Z','O cartaz que anuncia uma festa antes da música | Pé de Prosa','Paredes, postes e murais antecipam celebrações e mostram como uma comunidade escolhe convidar seus vizinhos.');
