INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a31','O objeto consertado que ensina a pedir ajuda','objeto-consertado-ensina-pedir-ajuda','Reparar um aparelho costuma revelar limites individuais e a importância de trocar conhecimento antes de descartar.','["A primeira tentativa foi apertar um parafuso. Depois vieram a pesquisa no manual, a ferramenta emprestada e a mensagem enviada a alguém que já tinha enfrentado o mesmo defeito.","Consertos lembram que autonomia não significa fazer tudo sem ajuda. Muitas soluções surgem quando alguém sabe formular a dúvida e encontra outra pessoa disposta a compartilhar experiência.","O objeto pode voltar a funcionar ou não. De todo modo, o processo deixa uma informação útil: quais sinais observar, quais limites respeitar e quando é melhor procurar assistência especializada."]','ideias','bia-sampaio','','Fotografia editorial relacionada à matéria: O objeto consertado que ensina a pedir ajuda','published',0,1,'2026-11-13T12:00:00.000Z','2026-11-13T12:00:00.000Z','O objeto consertado que ensina a pedir ajuda | Pé de Prosa','Reparar um aparelho costuma revelar limites individuais e a importância de trocar conhecimento antes de descartar.');
