INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a33','Aprender uma tarefa nova sem interromper o expediente','aprender-tarefa-nova-sem-interromper-expediente','Quando a formação acontece junto do trabalho, o tempo para perguntar e praticar precisa entrar no planejamento.','["Uma ferramenta foi atualizada na segunda-feira. Na terça, a equipe já precisava entregar o mesmo volume de trabalho usando menus diferentes e procedimentos que ninguém tinha experimentado por completo.","Aprender durante o expediente é comum, mas não deveria significar esconder as dúvidas. Orientações curtas, exemplos e um período para praticar tornam a mudança menos dependente da tentativa individual.","O planejamento melhora quando reconhece que adaptação também é trabalho. Quem aprende com tempo consegue registrar o que funcionou e compartilhar a descoberta com o restante da equipe."]','trabalho','lucas-reis','','Fotografia editorial relacionada à matéria: Aprender uma tarefa nova sem interromper o expediente','published',0,1,'2026-11-11T12:00:00.000Z','2026-11-11T12:00:00.000Z','Aprender uma tarefa nova sem interromper o expediente | Pé de Prosa','Quando a formação acontece junto do trabalho, o tempo para perguntar e praticar precisa entrar no planejamento.');
