INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a35','O tempo de descanso que cabe no meio do dia','tempo-descanso-meio-do-dia','Pausas curtas ajudam a reorganizar a atenção, mas só funcionam quando não viram mais uma tarefa a cumprir.','["O expediente tem intervalos oficiais e pequenas pausas que surgem entre uma atividade e outra. Algumas pessoas usam esses minutos para caminhar; outras preferem conversar ou simplesmente ficar em silêncio.","Descanso não é uma recompensa por ter produzido o suficiente. Ele faz parte de um ritmo de trabalho que precisa levar em conta concentração, fadiga e as condições em que as tarefas são realizadas.","Uma pausa possível não resolve toda a sobrecarga. Ainda assim, reconhecer seus limites e proteger um tempo sem demanda contínua ajuda a construir jornadas mais sustentáveis."]','trabalho','lucas-reis','','Fotografia editorial relacionada à matéria: O tempo de descanso que cabe no meio do dia','published',0,1,'2026-11-09T12:00:00.000Z','2026-11-09T12:00:00.000Z','O tempo de descanso que cabe no meio do dia | Pé de Prosa','Pausas curtas ajudam a reorganizar a atenção, mas só funcionam quando não viram mais uma tarefa a cumprir.');
