INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a36','A chuva vista da janela e a água no quintal','chuva-janela-agua-quintal','A mesma precipitação assume formas distintas conforme o terreno, a drenagem e os espaços permeáveis ao redor da casa.','["Da janela, a chuva pode parecer uma mudança de cenário. No quintal, ela encontra o solo, percorre calhas e revela se a água consegue se infiltrar ou se procura uma saída entre as construções.","Cada terreno faz parte de um entorno maior. Uma solução dentro de casa pode deslocar o escoamento para o lote vizinho; por isso, observar o caminho da água ajuda a evitar respostas que apenas mudam o problema de lugar.","Cuidar da drenagem começa com manutenção e conhecimento do próprio espaço. Em situações persistentes, orientação técnica local é importante para avaliar o que uma intervenção doméstica pode ou não resolver."]','natureza','davi-moraes','','Fotografia editorial relacionada à matéria: A chuva vista da janela e a água no quintal','published',0,1,'2026-11-08T12:00:00.000Z','2026-11-08T12:00:00.000Z','A chuva vista da janela e a água no quintal | Pé de Prosa','A mesma precipitação assume formas distintas conforme o terreno, a drenagem e os espaços permeáveis ao redor da casa.');
