INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a37','As plantas que chegam primeiro à praça','plantas-chegam-primeiro-praca','Jardins espontâneos mostram onde a terra permanece disponível e como pequenos espaços podem receber vida vegetal.','["Uma fresta perto do meio-fio recebe água de chuva e, semanas depois, abriga uma planta que ninguém planejou. A cena é pequena, mas mostra onde o solo ainda encontra condições para sustentar vida.","Nem toda vegetação espontânea é adequada para qualquer lugar. Algumas espécies podem atrapalhar a passagem ou exigir cuidados específicos, enquanto outras ajudam a cobrir áreas expostas e atraem insetos.","Observar antes de remover cria a oportunidade de entender o espaço. Jardins urbanos bem cuidados podem começar com uma escolha simples: reconhecer o que já está crescendo e planejar a partir do que o lugar suporta."]','natureza','davi-moraes','','Fotografia editorial relacionada à matéria: As plantas que chegam primeiro à praça','published',0,1,'2026-11-07T12:00:00.000Z','2026-11-07T12:00:00.000Z','As plantas que chegam primeiro à praça | Pé de Prosa','Jardins espontâneos mostram onde a terra permanece disponível e como pequenos espaços podem receber vida vegetal.');
