INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a38','A horta pequena que organiza a rotina da casa','horta-pequena-organiza-rotina-casa','Cuidar de poucas plantas cria uma sequência de observação, rega e colheita que se encaixa nos ritmos domésticos.','["Uma horta doméstica começa com uma escolha de espaço. Pode ser um vaso perto da janela, uma jardineira na varanda ou um canteiro compartilhado com outras pessoas da casa.","O cuidado envolve observar a luz, ajustar a rega e aceitar que nem toda tentativa dará certo na primeira estação. Plantas diferentes pedem condições diferentes, e conhecer o ambiente ajuda mais do que seguir um calendário rígido.","Mesmo pequena, a horta aproxima o cotidiano do ciclo dos alimentos. A colheita pode ser modesta, mas o aprendizado aparece toda vez que alguém nota uma folha nova ou percebe que a terra precisa de atenção."]','natureza','davi-moraes','','Fotografia editorial relacionada à matéria: A horta pequena que organiza a rotina da casa','published',0,1,'2026-11-06T12:00:00.000Z','2026-11-06T12:00:00.000Z','A horta pequena que organiza a rotina da casa | Pé de Prosa','Cuidar de poucas plantas cria uma sequência de observação, rega e colheita que se encaixa nos ritmos domésticos.');
