INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a39','A oficina de costura como ponto de encontro','oficina-costura-ponto-encontro','Um serviço de reparo também funciona como lugar de troca, recomendação e circulação de histórias do bairro.','["Na oficina, uma barra precisa de ajuste e a conversa começa pela escolha do tecido. Enquanto a máquina trabalha, alguém pergunta sobre uma rua próxima; outra pessoa recomenda um comércio que acabou de abrir.","A prestação de serviço cria relações que vão além da entrega de uma peça. O cliente volta porque conhece o trabalho, e a profissional reconhece hábitos, preferências e os detalhes que precisam de cuidado.","Esses pequenos negócios ajudam a manter conhecimento especializado perto de casa. Eles também mostram como trabalho e sociabilidade podem compartilhar o mesmo endereço sem perder a função de cada encontro."]','trabalho','maira-costa','','Fotografia editorial relacionada à matéria: A oficina de costura como ponto de encontro','published',0,1,'2026-11-05T12:00:00.000Z','2026-11-05T12:00:00.000Z','A oficina de costura como ponto de encontro | Pé de Prosa','Um serviço de reparo também funciona como lugar de troca, recomendação e circulação de histórias do bairro.');
