INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a40','A fotografia que só ganhou legenda anos depois','fotografia-ganhou-legenda-anos-depois','Identificar uma imagem antiga pode levar tempo; às vezes, a informação aparece quando alguém reconhece um detalhe ao fundo.','["A fotografia ficou anos sem identificação. As pessoas reconheciam os rostos, mas ninguém lembrava o lugar nem a ocasião. Uma janela ao fundo acabou oferecendo a pista que faltava quando um parente visitou a casa.","Legenda não é apenas uma data. Pode registrar quem aparece, o que estava acontecendo e quais dúvidas permanecem. Distinguir lembrança de certeza evita que uma hipótese vire descrição definitiva.","A imagem continuou a mesma, mas o arquivo mudou. Ao acrescentar contexto e reconhecer o que ainda não se sabe, a família tornou a fotografia mais legível para quem não participou daquele momento."]','cultura','ana-luz','','Fotografia editorial relacionada à matéria: A fotografia que só ganhou legenda anos depois','published',0,1,'2026-11-04T12:00:00.000Z','2026-11-04T12:00:00.000Z','A fotografia que só ganhou legenda anos depois | Pé de Prosa','Identificar uma imagem antiga pode levar tempo; às vezes, a informação aparece quando alguém reconhece um detalhe ao fundo.');
