INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a43','A praça não termina no desenho do mapa','praca-nao-termina-desenho-mapa','Bancos, caminhos e horários de uso ajudam a explicar por que alguns espaços públicos viram ponto de encontro e outros ficam apenas no trajeto.','["Vista de cima, uma praça parece uma área delimitada entre ruas. No nível de quem passa, ela é feita de decisões menores: por onde entrar, onde sentar, se há sombra, se é possível atravessar com carrinho ou caminhar sem desviar de obstáculos.","O mesmo espaço muda ao longo do dia. Uma área pode servir de passagem pela manhã, receber crianças no fim da tarde e abrigar uma conversa demorada depois que o movimento diminui. Esses usos não aparecem inteiros em uma planta ou em uma fotografia isolada.","A manutenção também compõe a experiência. Iluminação, bancos, limpeza e caminhos acessíveis sinalizam se o lugar foi pensado para permanência. Quando algo deixa de funcionar, a praça pode continuar aberta e, ainda assim, se tornar menos convidativa para parte da vizinhança.","Ouvir quem usa o espaço em horários diferentes ajuda a enxergar necessidades que uma visita rápida não revela. A pergunta deixa de ser apenas quantos metros existem e passa a incluir quem consegue chegar, ficar e participar.","Uma praça viva não precisa ter programação todos os dias. Ela precisa permitir que diferentes pessoas encontrem um jeito seguro e confortável de estar ali, sem que um único uso apague os demais."]','cidade','caio-nunes','','Fotografia editorial relacionada à matéria: A praça não termina no desenho do mapa','published',0,1,'2026-11-01T12:00:00.000Z','2026-11-01T12:00:00.000Z','A praça não termina no desenho do mapa | Pé de Prosa','Bancos, caminhos e horários de uso ajudam a explicar por que alguns espaços públicos viram ponto de encontro e outros ficam apenas no trajeto.');
