INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a44','O balcão onde a cidade aprende a pedir informação','balcao-cidade-aprende-pedir-informacao','Em pequenos comércios, perguntas sobre caminhos e serviços transformam o atendimento em uma rede informal de orientação cotidiana.','["Nem toda conversa que começa com um pedido termina numa compra. Alguém entra para perguntar onde fica uma rua, se o ônibus passa perto ou qual horário costuma ser mais tranquilo para resolver uma tarefa. O balcão vira um ponto de consulta porque está no caminho e porque há alguém disposto a responder.","Esse conhecimento é prático e localizado. Quem atende reconhece nomes de ruas, mudanças recentes e referências que fazem sentido para quem mora ali. A informação circula de pessoa para pessoa, quase sempre acompanhada de uma instrução simples: vire na esquina, procure a fachada clara, pergunte na próxima porta.","A rede tem limites. Uma orientação pode estar desatualizada, e nem todo estabelecimento consegue interromper o trabalho para ajudar. Por isso, ela complementa serviços oficiais e mapas, sem ocupar o lugar de informações que exigem confirmação.","Ainda assim, os encontros mostram como a confiança se constrói por repetição. O mesmo rosto aparece em dias diferentes, a conversa ganha continuidade e um endereço comercial passa a fazer parte do mapa cotidiano de quem vive por perto.","Observar esses pontos de apoio ajuda a entender que a vida de bairro depende também de espaços onde uma dúvida pode ser formulada sem cerimônia. São gestos breves, mas tornam a cidade um pouco mais legível."]','cotidiano','joana-melo','','Fotografia editorial relacionada à matéria: O balcão onde a cidade aprende a pedir informação','published',0,2,'2026-10-31T12:00:00.000Z','2026-10-31T12:00:00.000Z','O balcão onde a cidade aprende a pedir informação | Pé de Prosa','Em pequenos comércios, perguntas sobre caminhos e serviços transformam o atendimento em uma rede informal de orientação cotidiana.');
