INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a46','O que cabe em uma biblioteca de bairro','o-que-cabe-biblioteca-de-bairro','Além do empréstimo de livros, uma biblioteca próxima pode oferecer orientação, silêncio, encontros e acesso a ferramentas culturais.','["Uma biblioteca de bairro pode começar com estantes, mas sua função não se resume ao que está guardado nelas. Há quem procure um livro, quem precise de um lugar tranquilo para estudar e quem chegue para descobrir como participar de uma atividade.","O acervo ganha sentido quando as pessoas conseguem encontrá-lo. Sinalização compreensível, horários divulgados e ajuda para localizar títulos tornam a visita menos dependente de já conhecer as regras do espaço. A mediação não escolhe por cada leitor; abre caminhos para que cada um faça suas próprias escolhas.","Programações simples podem aproximar públicos diferentes: uma roda de leitura, uma oficina ou uma conversa sobre a memória do entorno. Não é necessário que toda visita tenha uma atividade marcada. O acesso ao silêncio e ao tempo de leitura também é um serviço importante.","Para funcionar, o espaço precisa de continuidade. Atualizar o catálogo, cuidar dos livros, manter os horários e ouvir quem usa a biblioteca são tarefas tão relevantes quanto inaugurar uma sala nova. Sem essa rotina, a porta aberta pode não significar acesso real.","Pensar a biblioteca como parte da infraestrutura cultural da cidade amplia a conversa sobre leitura. Ela é um lugar onde informação, convivência e autonomia podem se encontrar perto de casa."]','cultura','ana-luz','','Fotografia editorial relacionada à matéria: O que cabe em uma biblioteca de bairro','published',0,2,'2026-10-29T12:00:00.000Z','2026-10-29T12:00:00.000Z','O que cabe em uma biblioteca de bairro | Pé de Prosa','Além do empréstimo de livros, uma biblioteca próxima pode oferecer orientação, silêncio, encontros e acesso a ferramentas culturais.');
