INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a48','A cidade que se revela pelo caminho até a escola','cidade-revela-caminho-ate-escola','O trajeto diário reúne calçadas, travessias, horários e pequenas decisões que influenciam a experiência de crianças e acompanhantes.','["O percurso até a escola costuma ser conhecido passo a passo por quem o faz todos os dias. Uma calçada estreita, uma travessia sem sinalização ou a fila na entrada podem parecer detalhes separados, mas juntos definem quanto tempo e atenção a caminhada exige.","As condições variam conforme o horário. Veículos estacionados, entregas e concentração de pessoas alteram a passagem; uma rota confortável em um momento pode ficar difícil em outro. Por isso, observar o trajeto em diferentes dias oferece um retrato mais fiel do que uma visita pontual.","A presença de crianças muda a escala das decisões. Elas precisam de tempo para atravessar, visibilidade perto de esquinas e espaço para caminhar acompanhadas. Acessibilidade também beneficia pessoas idosas, quem usa cadeira de rodas e adultos que levam carrinhos ou bolsas.","Famílias e equipes escolares costumam conhecer problemas recorrentes, mas registrar onde e quando eles ocorrem ajuda a encaminhar pedidos com mais clareza. Uma descrição objetiva, acompanhada de localização e horário, pode tornar a conversa com os responsáveis pelo espaço público mais útil.","O caminho escolar ensina que mobilidade não é somente deslocamento rápido. É a possibilidade de chegar com segurança e autonomia, considerando os ritmos de quem usa a rua."]','cidade','pedro-alves','','Fotografia editorial relacionada à matéria: A cidade que se revela pelo caminho até a escola','published',0,1,'2026-10-27T12:00:00.000Z','2026-10-27T12:00:00.000Z','A cidade que se revela pelo caminho até a escola | Pé de Prosa','O trajeto diário reúne calçadas, travessias, horários e pequenas decisões que influenciam a experiência de crianças e acompanhantes.');
