INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a50','Quando o bairro decide cuidar de uma árvore','quando-bairro-decide-cuidar-arvore','A mobilização em torno de uma árvore combina afeto, conhecimento técnico e responsabilidade sobre o espaço compartilhado.','["Uma árvore na calçada costuma ser percebida primeiro pela sombra que oferece. Com o tempo, seus galhos, raízes e folhas entram na rotina de moradores, trabalhadores e pessoas que esperam ou passam por ali. Quando surge um problema, a preocupação se espalha para além de quem mora ao lado.","A vontade de ajudar precisa caminhar junto com informação adequada. Podas, cortes e intervenções em raízes podem exigir avaliação profissional e autorização local. Uma ação improvisada pode prejudicar a árvore ou criar riscos para quem circula.","O primeiro passo é descrever o que foi observado: galho quebrado, inclinação, conflito com fiação ou danos na calçada. Fotografias feitas de distância segura e a localização ajudam a encaminhar a situação aos serviços responsáveis sem colocar ninguém em perigo.","Enquanto a resposta não chega, o entorno pode combinar cuidados simples, como manter a área visível e avisar outras pessoas sobre um risco imediato. Cada tarefa precisa respeitar limites e não substituir profissionais quando há possibilidade de queda ou contato com rede elétrica.","Cuidar de uma árvore pública é também cuidar de um bem comum. O vínculo afetivo pode abrir a conversa, e a responsabilidade compartilhada mantém o cuidado informado e seguro."]','natureza','davi-moraes','','Fotografia editorial relacionada à matéria: Quando o bairro decide cuidar de uma árvore','published',0,1,'2026-10-25T12:00:00.000Z','2026-10-25T12:00:00.000Z','Quando o bairro decide cuidar de uma árvore | Pé de Prosa','A mobilização em torno de uma árvore combina afeto, conhecimento técnico e responsabilidade sobre o espaço compartilhado.');
INSERT INTO article_tags (article_id,tag_id) VALUES ('a50','bairro');
