INSERT INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a51','O trabalho invisível de manter uma casa funcionando','trabalho-invisivel-manter-casa-funcionando','Planejar compras, acompanhar prazos e antecipar necessidades compõem uma rotina de trabalho que raramente aparece na lista de tarefas domésticas.','["Uma casa não se mantém apenas com tarefas que deixam resultado visível. Antes de lavar uma roupa, alguém percebe que o cesto está cheio; antes de preparar uma refeição, outra pessoa verifica o que falta e ajusta o horário para que tudo fique pronto.","Esse trabalho de antecipação é difícil de contabilizar porque acontece em intervalos e pode ser confundido com uma característica pessoal. Na prática, exige memória, atenção e decisões contínuas. Quando fica concentrado em uma pessoa, até uma divisão aparentemente equilibrada pode depender de uma única central de planejamento.","Tornar as tarefas visíveis ajuda a distribuir também a responsabilidade de perceber e organizar. Uma lista compartilhada, por exemplo, funciona melhor quando cada pessoa acompanha sua parte sem esperar instruções para cada passo.","A divisão precisa ser realista. Horários, renda, saúde e condições de moradia impõem limites diferentes. Rever o arranjo com frequência permite identificar o que pode ser simplificado, compartilhado ou contratado, sem tratar a rotina como uma prova de eficiência.","Reconhecer o planejamento doméstico como trabalho muda a conversa. Em vez de discutir apenas quem executou a última tarefa, fica possível perguntar quem está sustentando a sequência inteira de decisões."]','trabalho','lucas-reis','','Fotografia editorial relacionada à matéria: O trabalho invisível de manter uma casa funcionando','published',0,1,'2026-10-24T12:00:00.000Z','2026-10-24T12:00:00.000Z','O trabalho invisível de manter uma casa funcionando | Pé de Prosa','Planejar compras, acompanhar prazos e antecipar necessidades compõem uma rotina de trabalho que raramente aparece na lista de tarefas domésticas.');
